def add(i,decision,rec,reason,ev,issues=None,proposed=None):
 a.append({'ordinal':i+1,'goalId':rows[i]['goalId'],'title':rows[i]['D']['currentTitleDe'],'descriptionDecision':decision,'profileRecommendation':rec,'scientificReasonDe':reason,'evidence':dict(zip(['essentialUnderstandingDe','essentialUnderstandingEn','observablePerformanceDe','observablePerformanceEn','transferExpectationDe','transferExpectationEn'],ev)),'contextFindings':issues or [],**({'proposedDescriptionDe':proposed[0],'proposedDescriptionEn':proposed[1]} if proposed else {})})
add(0,'revise','none','Die Einschränkung auf einfach besetzte Ausgangsorbitale ist als einfaches Elektronenpaarbindungsmodell korrekt, aber keine allgemeine Entstehungsregel aller Molekülbindungen. Den Modellstatus in D sichtbar machen; der ganze P-Körper behandelt Paarbildung, günstigen Abstand und koordinative Gegenfälle bereits zutreffend. Der direkte Kern-Hülle-Kontext muss nicht schon die neue Orbitalerklärung beherrschen.',[
'Im einfachen Elektronenpaarbindungsmodell können passende einfach besetzte Orbitale ein gemeinsames Paar mit entgegengesetzten Spins bilden; Anziehung und Abstoßung bestimmen einen günstigen Kernabstand.',
'In the simple electron-pair bonding model, compatible singly occupied orbitals can form a shared pair with opposite spins; attraction and repulsion determine a favourable internuclear distance.',
'Die lernende Person erklärt am H2-Modell, weshalb Elektronendichte zwischen den Kernen den Zusammenhalt ermöglicht und übermäßige Annäherung die Energie wieder erhöht.',
'The learner explains in an H2 model how electron density between nuclei supports bonding and why excessive approach raises energy again.',
'Bei einem neuen vorgegebenen H–Cl-Orbitalbild unterscheidet sie das bindende Paar von freien Paaren und begrenzt die Aussage auf das verwendete Modell.',
'With a fresh supplied H–Cl orbital diagram, they distinguish the bonding pair from lone pairs and limit the claim to the model used.'
],proposed=('Die lernende Person kann den Zusammenhalt von Atomen in Molekülen im einfachen Elektronenpaarbindungsmodell durch Überlagerung einfach besetzter Orbitale erklären.','The learner can explain the cohesion of atoms in molecules in the simple electron-pair bonding model through the overlap of singly occupied orbitals.'))
add(1,'revise','none','Die unbedingte Umkehrbarkeit verschiedener Formeldarstellungen ist bei Isomerie nicht gegeben. Die erforderliche Strukturinformation als Bedingung ausdrücklich nennen; der ganze P-Körper zeigt C2H6O-Isomere und die Informationsgrenze bereits. Symbolsprache ist eine geeignete Grundlage, die Darstellungsumwandlung bleibt die eigene neue Leistung.',[
'Formeldarstellungen enthalten unterschiedlich viel Information: Atomzahlen bestimmen nicht immer Verknüpfung, freie Elektronenpaare oder räumliche Anordnung.',
'Formula representations contain different amounts of information: atom counts do not always determine connectivity, lone pairs or spatial arrangement.',
'Die lernende Person überführt eine vorgegebene Molekülstruktur in geeignete Formeln und begründet anhand einer konkreten Frage, welche Information die gewählte Darstellung zeigt.',
'The learner converts a supplied molecular structure into suitable formulas and explains which information the chosen representation provides for a specific question.',
'An zwei neuen Strukturen mit gleicher Summenformel erklärt sie die fehlende eindeutige Rückübersetzung und wählt eine Darstellung, die den Strukturunterschied sichtbar macht.',
'For two fresh structures sharing a molecular formula, they explain why unique inversion is impossible and choose a representation that reveals the structural difference.'
],proposed=('Die lernende Person kann auf Grundlage ausreichender Strukturinformationen verschiedene Formeldarstellungen von Molekülen ineinander überführen und situationsgerecht eine geeignete Darstellung auswählen.','The learner can convert different formula representations of molecules into one another using sufficient structural information and select an appropriate representation for the situation.'))
add(2,'keep','none','D verknüpft Molekülgestalt und Lewis-Darstellung fachlich richtig; P deckt freie Paare, Domänenzahl, Doppelbindungen und einen echten Geometriewechsel ab. Der neue direkte Darstellungs-Vorgänger ist eine geeignete Grundlage; exakte Winkel oder Polarität werden nicht unbemerkt Pflicht.',[
'Im EPA-Modell bestimmt die Anordnung bindender und freier Elektronenbereiche die Molekülgestalt; Elektronenbereichsgeometrie und Lage der Atome sind zu unterscheiden.',
'In VSEPR, bonding and lone electron domains determine molecular shape; electron-domain geometry must be distinguished from the positions of atoms.',
'Die lernende Person zählt Elektronenbereiche in gegebenen Lewis-Strukturen und begründet damit lineare, gewinkelte oder tetraedrisch abgeleitete Gestalten.',
'The learner counts electron domains in supplied Lewis structures and uses them to explain linear, bent or tetrahedrally derived shapes.',
'Bei NH3 statt CH4 erklärt sie trotz gleicher Domänenzahl die trigonal-pyramidale Gestalt durch das freie Paar, ohne daraus exakte Winkel zu erfinden.',
'For NH3 instead of CH4, they explain the trigonal-pyramidal shape from the lone pair despite equal domain count, without inventing exact angles.'
],issues=['Bild separat korrigierbedürftig: Im rechten Methan-Keilstrichbild sind zwei Bindungen als volle Keile und nur eine als gestrichelter Keil gezeichnet; die Benennung als tetraedrische Geometrie wird dadurch räumlich missverständlich. D/P sind hiervon getrennt zu beurteilen.'])
add(3,'keep','none','D beschreibt eine zusammenhängende Modellierungsleistung zu Stoffkreisläufen. Die ganzen P-Fälle trennen den ausdrücklich molekularen CO2-Austausch von Reaktionen, erhalten Elemente und vermeiden einen Energiekreislauf. Reaktionsmerkmale plus Redox sind passende Grundlagen; kein vollständiger naturwissenschaftlicher oder amtlicher Kreislaufumfang wird behauptet.',[
'Stoffkreisläufe verbinden chemische Stoffumwandlungen mit physikalischem Transport und Speicherung; Elemente bleiben erhalten, während Stoffformen und Energiebereitstellung wechseln.',
'Matter cycles connect chemical transformation with physical transport and storage; elements are conserved while substance forms and energy supply change.',
'Die lernende Person verfolgt ein Element durch einen gegebenen natürlichen Kreislauf, ordnet jeden Schritt begründet als chemisch oder physikalisch ein und erklärt passende Summenbilanzen.',
'The learner traces an element through a supplied natural cycle, classifies each step as chemical or physical with reasons and explains suitable overall balances.',
'Im neuen technischen Kalkkreislauf trennt sie Stoffbilanz und Wärmezufuhr und begründet, weshalb eine geschlossene Idealbilanz keine vollständige CO2-Rückbindung oder Klimaneutralität beweist.',
'In a fresh technical lime cycle, they separate material balance from heat input and explain why an ideal closed balance proves neither complete CO2 recapture nor climate neutrality.'
],issues=['Bild Wasserzweig: Die gemeinsame Beschriftung Wasserdampf/Wolke sollte ausdrücklich Dampf von kondensierten Wolkentröpfchen unterscheiden; diese Medienpräzisierung erweitert D nicht.'])
add(4,'keep','none','Die vier Teilhandlungen sind verknüpfte Darstellungen einer Protolysekompetenz und fachlich äquivalent übersetzt. P zeigt Wasser in beiden Rollen sowie einen geladenen Ampholyten mit Atom-/Ladungsprüfung. Direkte Teilchen- und Formelgrundlagen reichen; quantitatives Gleichgewicht wird nicht still vorausgesetzt.',[
'Brønsted-Säure und -Base sind Teilchenrollen als Protonendonator und Protonenakzeptor; korrespondierende Paare unterscheiden sich um genau ein Proton und Wasser kann beide Rollen übernehmen.',
'Brønsted acid and base are species roles as proton donor and acceptor; conjugate pairs differ by one proton and water can take either role.',
'Die lernende Person formuliert ausgeglichene Protolysegleichungen, markiert den Protonenweg und beide Paare und unterscheidet die beteiligten Teilchen vom Stoffgemisch Lösung.',
'The learner writes balanced protolysis equations, marks the proton path and both pairs, and distinguishes participating species from the solution mixture.',
'Mit vorgegebenen Teilchen eines neuen geladenen Ampholyten entwickelt sie beide möglichen Wasserschritte und erklärt, warum formale Amphoterie keine gleiche Umsatzstärke oder Neutralität beweist.',
'Using supplied species of a fresh charged ampholyte, they construct both water reactions and explain why formal amphoterism proves neither equal reaction extent nor neutrality.'
])
add(5,'keep','none','D benennt den entscheidenden Unterschied der übertragenen Einheit und verwendet chemisch geeignete Beispiele. P trennt Carbonat-Protonierung mit Gasfolgereaktion von Metalloxidation und behandelt NH3 als Gegenfall zu Ladung gleich Oxidationszahl. Beide direkten Vorgänger tragen diese Vergleichsleistung.',[
'Redoxreaktionen ändern Oxidationszahlen durch Elektronenübertragung; Brønsted-Reaktionen übertragen Protonen. Gasentwicklung oder eine Ladungsänderung allein bestimmen keinen Reaktionstyp.',
'Redox reactions change oxidation numbers through electron transfer; Brønsted reactions transfer protons. Gas evolution or a change of species charge alone identifies neither reaction type.',
'Die lernende Person erklärt an Metall/Säure und Carbonat/Säure anhand der Teilchenbilanzen, welche Einheit übertragen wird und weshalb die Gasbildung unterschiedliche Ursachen hat.',
'The learner uses species balances for metal/acid and carbonate/acid reactions to explain what is transferred and why gas evolution has different causes.',
'In einem neuen gasfreien Vergleich Zn/Cu2+ und NH3/H3O+ ordnet sie Donator und Akzeptor samt übertragener Einheit zu und widerlegt Oxidation allein aus positiverer Ionenladung.',
'In a fresh gas-free Zn/Cu2+ versus NH3/H3O+ comparison, they identify donor, acceptor and transferred entity and reject oxidation inferred solely from more positive ion charge.'
])
add(6,'keep','none','D hält Planung, tatsächliche Durchführung und quantitative Auswertung zusammen. Der ganze aktuelle P erwirbt Konzentrationsbezug im Ziel selbst aus Stoffmenge/Volumen, berücksichtigt formale Säurekonzentration, Aliquot und Verdünnung und verlangt einen echten Praxisbeleg. Daher entsteht durch Weglassen eines vorausgesetzten Konzentrationsziels kein fachliches Loch. Grundlegende Mol-, Gleichungs-, Brønsted- und Sicherheitslehren sind direkt vorhanden.',[
'Bei einer Titration verknüpft die Reaktionsstöchiometrie das gemessene Maßlösungsvolumen mit der analytischen Stoffmenge im ursprünglichen Probenaliquot; Konzentration bezieht diese auf dessen Volumen.',
'In titration, reaction stoichiometry links measured titrant volume to the analytical amount in the original sample aliquot; concentration relates that amount to its volume.',
'Die lernende Person plant und führt unter geeigneter Aufsicht eine Titration tatsächlich aus, dokumentiert Anfangs-/Endstand und begründet Indikatorwahl, Stoffmengenverhältnis und Konzentrationsrechnung mit Einheiten.',
'The learner actually plans and performs a titration under suitable supervision, records initial/final readings and justifies indicator choice, amount ratio and concentration calculation with units.',
'Bei einer neuen zweiprotonigen Probe mit quantitativer Verdünnung leitet sie Reaktionsfaktor und Rückrechnung zur Originalprobe selbst her; geänderte Aliquotgröße verändert den Verbrauch, nicht die Probenkonzentration.',
'For a fresh diprotic sample with quantitative dilution, they independently derive the reaction ratio and original-sample calculation; a changed aliquot changes consumption, not sample concentration.'
],issues=['Eine separate konkret freigegebene Ausführungs-/Gefährdungs-SOP ist im Materiallocator nicht gebunden. Das begrenzt eine konkrete Laborfreigabe; es rechtfertigt keine Durchführungspunkte aus den Papierfällen und keine Abschwächung des D-Operators.'])
add(7,'keep','none','D wahrt den qualitativen Umfang zweier eng zusammengehöriger Raffinerieprozesse. P verlangt die zentrale Trennung vorhandener Stoffe gegenüber chemischem Molekülumbau, bilanziert Beispielprodukte und vermeidet garantierte Ausbeuten. Hydrocarbon-Grundlagen und Reaktionsmerkmale sind geeignet.',[
'Fraktionierte Destillation trennt vorhandene Komponenten nach Siedeverhalten, während thermisches Cracken Moleküle chemisch umwandelt und typischerweise kürzere Alkane und Alkene erzeugt.',
'Fractional distillation separates existing components by boiling behaviour, whereas thermal cracking chemically converts molecules, typically producing shorter alkanes and alkenes.',
'Die lernende Person erklärt das Temperaturgefälle der Kolonne, ordnet leichte und schwere Fraktionen zu und unterscheidet es von einem atomar bilanzierten Crackmodell.',
'The learner explains the column temperature gradient, assigns light and heavy fractions and distinguishes separation from an atom-balanced cracking model.',
'Bei verändertem Bedarf an leichten Produkten erklärt sie, weshalb eine andere Abzugshöhe allein keine neuen kurzen Moleküle erzeugt und weshalb die Crackbilanz kein reales Produktspektrum festlegt.',
'With a changed demand for light products, they explain why a different withdrawal height alone creates no new short molecules and why a cracking balance does not fix the actual product distribution.'
])
add(8,'keep','none','D verbindet Anwendungen mit begründeter ökologischer Bewertung ohne pauschale Schadens- oder Nutzenaussage. P verändert die Nutzungsform von Brennstoff/Kunststoff zu Schmieröl/Bitumen, grenzt Einzelinformationen von Ökobilanz ab. Der Raffinerie-Vorgänger ist als fachliche Einordnung geeignet.',[
'Erdölprodukte können als Energieträger oder stofflich genutzt werden; ihr Nutzen und ihre Umweltpfade hängen von Funktion, Freisetzung, Nutzungsdauer und Entsorgung ab.',
'Petroleum products can serve as fuels or materials; benefits and environmental pathways depend on function, release, service life and disposal.',
'Die lernende Person ordnet konkrete Produkte ihren Funktionen zu und begründet Nutzen sowie Umweltfolgen aus gegebenen Informationen, ohne eine vollständige Ökobilanz daraus abzuleiten.',
'The learner assigns products to functions and uses supplied information to explain benefits and environmental consequences without claiming a complete life-cycle assessment.',
'Bei Schmieröl und Bitumen statt eines Kraftstoffs erklärt sie Leckage- und Abriebpfade und begründet eine geeignete Maßnahme, obwohl die Produkte beim Gebrauch nicht verbrannt werden.',
'For lubricant and bitumen instead of fuel, they explain leakage and abrasion pathways and justify a suitable measure even though these products are not burned during use.'
])
add(9,'keep','none','D beschränkt sich auf Begründung gegebener oder bestimmter Enthalpien und relative Systemlagen. Der ganze P verlangt keine fremde Bindungsenergiesummen-Rechenkompetenz, nutzt gemeinsame stöchiometrische Basis und einen Phasenwechsel als echte Modellgrenze. Energie-/Enthalpie-, Bindungs- und Wechselwirkungsgrundlagen sind vorhanden.',[
'Bindungsbruch benötigt und Bindungsbildung liefert Energie; ihre Bilanz erklärt Reaktionsenthalpien nur auf gemeinsamer Stoffmengen- und Zustandsbasis. Phasenwechsel können zusätzliche Beiträge liefern.',
'Bond breaking requires and bond formation releases energy; their balance explains reaction enthalpies only on a common amount and state basis. Phase changes can add contributions.',
'Die lernende Person begründet mit gegebenen Bindungsbudgets, weshalb zwei Reaktionen unterschiedlich viel Energie abgeben, und ordnet die jeweiligen Produkt- und Eduktsysteme relativ ein.',
'The learner uses supplied bond budgets to explain differing energy release in two reactions and compares each product system with its reactants.',
'Bei Wasser als flüssigem statt gasförmigem Produkt erklärt sie den Enthalpieunterschied durch zusätzliche intermolekulare Stabilisierung und begrenzt das Gas-Bindungsmodell.',
'For liquid rather than gaseous water product, they explain the enthalpy difference through additional intermolecular stabilization and state the gas-bond model limitation.'
])
add(10,'keep','revise','D nennt zutreffend Dipol-Dipol-Wechselwirkungen und Wasserstoffbrücken. Der ganze P prüft jedoch nur OH/H-Brücken gegenüber unpolaren Resten und deren Verlängerung; eine eigenständige Anwendung permanenter Dipolkräfte ohne H-Brücken-Donator bleibt nicht ausdrücklich beobachtbar. Ergänze einen passenden gegebenen Carbonyl-/Etherfall im P, ohne D oder die direkte allgemeine Wechselwirkungsgrundlage zu erweitern.',[
'Siedeverhalten und Wasserlöslichkeit hängen von intermolekularen Wechselwirkungen ab; permanente Dipole und Wasserstoffbrücken sind zu unterscheiden und gegenüber unpolaren Molekülanteilen abzuwägen.',
'Boiling behaviour and water solubility depend on intermolecular interactions; permanent dipoles and hydrogen bonding must be distinguished and weighed against nonpolar molecular parts.',
'Die lernende Person erklärt Eigenschaftsunterschiede vergleichbarer organischer Stoffe anhand ihrer Strukturen und unterscheidet Dipol-Dipol-Anziehung von möglicher Wasserstoffbrückendonator- und -akzeptorwirkung.',
'The learner explains property differences between comparable organic substances from their structures and distinguishes dipole attraction from possible hydrogen-bond donor and acceptor behaviour.',
'An einem neuen Molekül mit polarer Carbonylgruppe ohne OH-Donator erklärt sie seine Wechselwirkungen untereinander und mit Wasser und begrenzt daraus abgeleitete Löslichkeits- oder Siedetrends.',
'For a fresh molecule with a polar carbonyl group but no OH donor, they explain interactions among its molecules and with water and qualify the resulting solubility or boiling trends.'
])
add(11,'keep','none','D und P verwenden ein ausdrücklich qualitatives Donor-/Akzeptororbitalmodell, trennen Paarherkunft von Oxidationszahl und Fehling-Komplexbildung von späterer Cu(I)-Bildung. Bindungstypen und Redoxbegriffe sind geeignete direkte Lehrer; weder der vollständige EPA-Winkelkurs noch echte Fehling-Ausführung ist universal für diesen Erklärungsfall nötig. RP57 stützt den LK-Kern, RP58/8.7 bleiben optionale vertiefte Theorie; Fehling/ganzer P bleibt eigene operationalisierte Ergänzung, keine volle amtliche Gleichsetzung.',[
'Bei koordinativer Bindungsbildung liefert ein besetztes Ligandenorbital ein freies Elektronenpaar an ein geeignetes unbesetztes Zentralteilchenorbital; das entstandene gemeinsame Paar ist keine freie Elektronenübertragung im Redoxsinn.',
'Coordinate-bond formation uses a filled ligand orbital donating a lone pair to a suitable empty central-species orbital; the shared bonding pair is not free-electron transfer in the redox sense.',
'Die lernende Person erläutert am gegebenen Cu(II)-Tartrat-Fragment die Donor-/Akzeptorrollen und erklärt, warum Komplexierung Kupfer(II) in alkalischer Fehling-Lösung löslich hält.',
'The learner explains donor and acceptor roles in a supplied Cu(II)-tartrate fragment and why complexation keeps copper(II) soluble in alkaline Fehling solution.',
'Bei einem neuen Donorangebot mit beziehungsweise ohne verfügbares Paar prüft sie die Bindungsmöglichkeit im Modell und erklärt, warum ein Koordinationspfeil weder Cu(I) noch eine vollständige Komplexgeometrie beweist.',
'For fresh donor proposals with and without an available pair, they assess bonding within the model and explain why a coordination arrow establishes neither Cu(I) nor complete complex geometry.'
])
add(12,'keep','none','D begrenzt das Ziel auf pH-abhängige Ladungsformen und Amphoterie. P zeigt Glycin und eine zusätzliche Lysin-Seitenkettengruppe mit vorgegebenen pKa-Werten; keine Elektrophorese oder Laborpraxis wird Pflicht. Brønsted und funktionelle Gruppen tragen dies, Orientierung liefert keine fachliche Vorkenntnis.',[
'Protonierbare Amino- und Carboxygruppen bestimmen je nach pH die vorherrschenden Ladungsformen; ein Zwitterion hat innere Ladungen auch bei Nettoladung null.',
'Protonatable amino and carboxyl groups determine predominant charge forms according to pH; a zwitterion remains internally charged even with zero net charge.',
'Die lernende Person zeichnet anhand gegebener pKa-Werte vorherrschende Glycinformen, bilanziert ihre Ladungen und erklärt Protonenaufnahme beziehungsweise -abgabe als Ursache amphoteren Verhaltens.',
'The learner uses supplied pKa values to draw predominant glycine forms, balances their charges and explains proton uptake and donation as the basis of amphoteric behaviour.',
'Bei einer neuen Aminosäure mit zusätzlicher ionisierbarer Seitenkette bezieht sie alle Gruppen in die Ladungsbilanz ein und behandelt dominante Formen als Gleichgewichtsverteilung statt hundertprozentiger Einheitlichkeit.',
'For a fresh amino acid with an additional ionizable side chain, they include every group in the charge balance and treat dominant forms as equilibrium distributions rather than complete uniformity.'
],issues=['P-Fall1 schreibt deutsche Dezimalwerte als „2, 3 und 9, 6“; als 2,3 und 9,6 ohne Binnenleerzeichen eindeutiger setzen. Bild pH2 zeigt eine dominante Form, keine ausschließliche Spezies.'])
add(13,'keep','revise','D verknüpft einen kontrollierten tatsächlichen Nachweis mit korrekter Koordinationsdeutung. Die zwei ganzen Prozedurfälle sind echt handlungsbezogen, aber verdünntes Eiklar/Gelatine und Tropfenvolumen bleiben unbestimmt; bei fester Kupferzugabe kann Überschuss den Befund überlagern. Eine gebundene konkrete Sicherheits-/Entsorgungsanleitung fehlt. P sollte geeignete Proben-/Reagenzbedingungen, Schutz, Abfallweg und Positivkontroll-Gültigkeit explizit binden. Das ist keine Forderung nach bereits ausgeführtem Humanversuch.',[
'Der Biuret-Nachweis beruht in alkalischer Lösung auf Cu(II)-Koordination geeigneter Peptidgruppen; violette Komplexfarbe ist von blauem Reagenz oder Cu(OH)2-Niederschlag zu unterscheiden.',
'The biuret assay relies on Cu(II) coordination by suitable peptide groups in alkaline solution; violet complex colour must be distinguished from blue reagent or Cu(OH)2 precipitate.',
'Die lernende Person führt eine betreute Serie mit geeigneter Protein-Positivkontrolle und Negativkontrollen tatsächlich durch, dokumentiert Farben und Niederschläge und begründet den Befund mit Peptidgruppen.',
'The learner actually performs a supervised series with a suitable protein positive control and negative controls, records colours and precipitates and explains findings using peptide groups.',
'Bei einer neuen verdünnten Peptidprobe trennt sie einen gültigen negativen Befund unterhalb der Nachweisgrenze von versagenden Kontrollen und behauptet weder völlige Proteinabwesenheit noch Aminosäureidentität.',
'For a fresh diluted peptide sample, they distinguish a valid negative below detection limits from failed controls and claim neither complete protein absence nor amino-acid identity.'
])
add(14,'keep','none','D und ganze Materialfälle halten Rohstoffherkunft, Polymerchemie und Entsorgungsweg auseinander. Beide Beutelrouten verwenden 20g PE je Beutel; die Werte 30/20g CO2e und Mehrweg-Break-even20/12 sind korrekt. Kunststoffklassen reichen als direkter Ausgang; Hydrolyse-/Recyclingreaktionsausführung ist keine zwingende vorgängige Fähigkeit. Offizielle BY13-Klausel unterstützt den Vergleich, nicht eine vollumfängliche LCA.',[
'Rohstoffherkunft allein bestimmt weder Abbaubarkeit noch Umweltbilanz; ein Vergleich braucht gleichen Nutzen, benannte Systemgrenzen und transparente Nachhaltigkeitskriterien.',
'Feedstock origin alone determines neither biodegradability nor environmental balance; comparison requires equal service, stated system boundaries and transparent sustainability criteria.',
'Die lernende Person vergleicht gegebene fossile und biobasierte Rohstoffrouten auf gleicher funktionaler Basis, trennt Emissionen von Energie und begründet ein bedingtes Urteil mit Zielkonflikten.',
'The learner compares supplied fossil and biobased routes on an equal functional basis, distinguishes emissions from energy and justifies a conditional judgment including trade-offs.',
'Bei geändertem Strommix und Nutzungszahl eines Mehrwegprodukts berechnet und interpretiert sie den neuen Vergleich und erklärt, weshalb Sammlungsquote keine Recyclingausbeute und erneuerbare Herkunft keine Klimaneutralität beweist.',
'With changed electricity mix and reusable-product lifetime, they calculate and interpret the new comparison and explain why collection rate is not recycling yield and renewable origin does not prove climate neutrality.'
])
add(15,'keep','none','Die ganze aktuelle Anlage umfasst neben Modellfällen eine konkrete ausführbare FeNCS-Untersuchung mit beobachtbaren eigenen Handlungen. Original UCI-Methode, Adaptions-SOP, Rohfixture und Studienoriginale wurden gelesen. Die Grenzen s=epsilon*l*alpha und x<=A/s sind korrekt; 86,67µM Obergrenze lässt beide Eduktreste positiv. Authentische Publikationskritik und synthetische Auswertung bleiben ohne Durchführungspunkte. Die direkte Sicherheits-/Reaktionsmerkmale-Grundlage genügt für diese im Ziel angeleitete Untersuchung; kein neues vollständiges Mess-/Kinetikziel voraussetzen.',[
'Im chemischen Gleichgewicht können Edukte und Produkte zugleich bei konstanter makroskopischer Zusammensetzung vorliegen; gleiche nichtnullige Hin- und Rückraten sind die dynamische Modelldeutung, keine Aussage gleicher Stoffmengen.',
'At chemical equilibrium, reactants and products can coexist with constant macroscopic composition; equal nonzero forward and reverse rates are the dynamic model interpretation, not equal amounts.',
'Die lernende Person führt die geeignete kontrollierte chemische Untersuchung tatsächlich aus, bindet Produktbefund und begründete positive Eduktreste an denselben Originalzustand und verbindet dies mit Stoff- und Teilchenmodell.',
'The learner actually performs the suitable controlled chemical investigation, binds product evidence and justified positive reactant residuals to the same original state and connects this with substance and particle models.',
'Bei Verdünnung oder gescheiterter Matrix-/Spektralkontrolle behandelt sie die Probe als neuen Zustand und sperrt die alte 1:1-Schlusskette; bei offenem Stoffaustausch unterscheidet sie stationäre Bilanz von gleichen Reaktionsraten.',
'After dilution or failed matrix/spectral controls, they treat the sample as a new state and withhold the old 1:1 inference; with open material exchange, they distinguish steady balances from equal reaction rates.'
],issues=['Gültigkeit ist bedingt durch das verdünnte1:1-Modell und übertragbare molare Absorptivität; Bandform/Linearität beweisen nicht vollständige Speziation. Diese Einschränkung steht im ganzen aktuellen P/SOP. Keine realen Durchführungsergebnisse oder Humanfreigaben liegen durch diesen Review vor.'])
add(16,'keep','none','D verlangt bewusst Deutung bereitgestellter Daten, keine eigene Aufnahme oder zusätzliche pH-Rechenpflicht. T05, T08 und der ganze qualitative Glycinfall sind vorhanden und passen zu den erläuterten Spezies-/Stärke-/Indikatorgrenzen. Direkte Brønsted-/pK-Lehrer reichen. Bildfehler dürfen nicht zur richtigen Speziesaussage hochgestuft werden.',[
'Titrationskurven unterscheiden Stoffmenge, Säure-/Basenstärke und pH-bestimmende Teilchen; Äquivalenz, Halbäquivalenz, Pufferbereich und Indikatorendpunkt haben verschiedene Bedeutungen.',
'Titration curves distinguish amount, acid/base strength and pH-controlling species; equivalence, half-equivalence, buffering and indicator endpoint have different meanings.',
'Die lernende Person liest vorgelegte Kurvendaten, erklärt die vorhandenen Bereiche mit den maßgeblichen Teilchen und begründet passende Indikatorintervalle ohne eindeutige Stoffidentität zu erfinden.',
'The learner reads supplied curve data, explains existing regions using controlling species and justifies suitable indicator intervals without inventing unique chemical identity.',
'Bei einer fallenden Basenkurve oder einer gegebenen zweistufigen Aminosäurekurve ordnet sie die neuen konjugierten Paare zu und erklärt, weshalb Halbvolumen nicht allgemein pKa und Äquivalenz nicht allgemein pH7 bedeutet.',
'For a falling base curve or supplied two-stage amino-acid curve, they identify the new conjugate pairs and explain why half-volume does not universally mean pKa and equivalence does not universally mean pH7.'
],issues=['Konkreter Bildfehler in Original und gebundener PDF-Seite17: „Start: nur Säure“ und „Äquivalenzpunkt: nur Salz“ sind als Speziesaussagen falsch; die Protolyse/Hydrolyse erzeugt weitere Teilchen. Auch im Überschuss ist OH− statt molekularer NaOH die pH-bestimmende Spezies. D/P korrekt, Bild benötigt eigene Korrektur und Neubindung.'])
add(17,'keep','none','D umfasst die integrierte Erklärung von Korrosion und Schutz. Ganze eqrk16-Fälle behandeln Metall-/Elektrolytkreis, Zink/Zinn, Kontakt, Belüftung, Flächen und Ratenbegrenzung richtig. Direkte galvanische Zell- und Redoxgleichungslehrer sind passend. NI26 stützt Lokalelement/Opferanode für gA/eA; dort separat verlangte echte Experimente und Bewertung werden durch dieses Erklärungsziel nicht mitabgeschlossen.',[
'Elektrochemische Korrosion koppelt anodische Metallauflösung mit kathodischer Reduktion über elektronische und ionische Wege; Beschichtungen und Opferanoden wirken auf unterschiedliche Teile dieses Systems.',
'Electrochemical corrosion couples anodic metal dissolution to cathodic reduction through electronic and ionic paths; coatings and sacrificial anodes affect different parts of this system.',
'Die lernende Person erklärt Teilreaktionen und Ladungswege eines Lokalelements und begründet Barriere- beziehungsweise Opferwirkung einschließlich ihrer Kontakt- und Defektbedingungen.',
'The learner explains half-reactions and charge paths of a local cell and justifies barrier and sacrificial protection including contact and defect conditions.',
'Bei unterbrochenem Zinkkontakt oder verändertem Sauerstoffangebot leitet sie den geänderten Angriff begründet ab und trennt thermodynamische Richtung von einer ohne Messung unbekannten Korrosionsrate.',
'With broken zinc contact or changed oxygen supply, they explain the resulting attack and distinguish thermodynamic direction from corrosion rate unknown without measurements.'
])
add(18,'keep','none','D begrenzt elektrische Arbeit auf angegebene Mess-/Modellbedingungen statt sie mit Reaktionsenthalpie gleichzusetzen. P liefert ausdrücklich gleichzeitige belastete U/I-Intervalle und unterscheidet -DeltaG-Maximum. Rechnungen36J,40J und Leerlauf0J stimmen. Galvanische Grundlagen und Energie-/Enthalpieverständnis sind passende Lehrer; kein Nernst- oder Elektrolyseabschluss wird verlangt.',[
'Elektrische Arbeit einer belasteten Zelle ergibt sich aus gleichzeitigem Spannungs- und Stromverlauf über die Zeit; sie ist umgewandelte Energie und nicht pauschal der Betrag der Reaktionsenthalpie.',
'Electrical work from a loaded cell follows simultaneous voltage and current over time; it is converted energy and is not universally the magnitude of reaction enthalpy.',
'Die lernende Person bestimmt Arbeit aus konstanten oder stückweise konstanten Messintervallen mit Einheiten und begrenzt die energetische Aussage auf dieselbe umgesetzte Portion und die gegebenen Bedingungen.',
'The learner determines work from constant or piecewise constant measurement intervals with units and limits the energy interpretation to the same converted portion and stated conditions.',
'Bei unterbrochenem Außenkreis erklärt sie trotz Leerlaufspannung null abgegebene Arbeit; bei veränderlichem Verlauf widerlegt sie ein ungewichtetes Produkt getrennter Mittelwerte.',
'With an interrupted external circuit, they explain zero delivered work despite open-circuit voltage; for a changing trace, they reject an unweighted product of separate averages.'
])
add(19,'keep','none','D verbindet Übertragung des galvanischen Prinzips und darauf beruhendes Urteil als eine materialgestützte Anwendung. Ganze Fälle behalten Primärzellcharakter, Ladungswege, nutzbare Energie, Spannung/Anschluss und gesellschaftliche Kriterien. Der frische Nutzungs-/Lagerungswechsel ist echter Transfer;2→2,4Wh bleibt korrekt als Zahlenübung abgegrenzt. Ein galvanischer Lehrer genügt, Nernst-/Elektrolyseoperationen sind hier keine generellen Lehrer.',[
'Primärzellen nutzen getrennte Oxidation und Reduktion mit äußerem Elektronen- und innerem Ionentransport; geeignete Batteriewahl hängt von Spannung, Last, nutzbarer Energie, Lagerung und gesellschaftlichen Kriterien ab.',
'Primary cells use separated oxidation and reduction with external electron and internal ion transport; suitable choice depends on voltage, load, usable energy, storage and social criteria.',
'Die lernende Person überträgt das galvanische Prinzip auf zwei vorgegebene Primärtypen und begründet deren Eignung für einen konkreten Bedarf samt Kosten-, Rohstoff- und Entsorgungsgrenzen.',
'The learner applies the galvanic principle to two supplied primary types and justifies suitability for a concrete demand including cost, resource and disposal limits.',
'Beim Wechsel von kontinuierlichem Betrieb zu monatelanger Vorratshaltung mit kleinerem Energiebedarf überprüft sie das Urteil anhand Luftzugang, Aktivierungszustand und bestätigtem Geräteanschluss neu.',
'When changing from continuous operation to months of storage with lower energy demand, they reassess the judgment using airflow, activation state and verified device connection.'
])
